import sys
sys.path.insert(0,'/downloads/fiqh-alruh-source/gen')
import lib
head,W,R,S=lib.load()
def H_(i,t,d,ref): return {'id':i,'t':t,'d':d,'kind':'حديث','ref':ref}
add={
'duha':[('why',H_('m2','ركعتا الضحى تجزئان عن صدقة المفاصل','عن أبي ذر عن النبي ﷺ: يصبح على كل سلامى من أحدكم صدقة، فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويجزئ من ذلك ركعتان يركعهما من الضحى. فالحديث يعدّ أعمال الخير صدقات عن مفاصل الجسم، ويجعل ركعتي الضحى كافيتين عن ذلك كله. وهذا نص الحديث، وأما عدد ركعات الضحى وخلاف المذاهب في حكمها ففي تبويب الخلاف.','صحيح مسلم (720). https://sunnah.com/muslim:720'))],
'rawatib':[('why',H_('m2','بيت في الجنة','عن أم حبيبة: سمعت رسول الله ﷺ يقول: من صلى اثنتي عشرة ركعة في يوم وليلة بني له بهن بيت في الجنة. قالت أم حبيبة: فما تركتهن منذ سمعتهن من رسول الله ﷺ. هذا نص الحديث في فضل المحافظة على اثنتي عشرة ركعة في اليوم والليلة، وتفصيل أي الركعات هي وخلاف المذاهب في عددها ففي الخلاف، ولم يرد هذا التفصيل في هذا الحديث.','صحيح مسلم (728 أ). https://sunnah.com/muslim:728a'))],
'tashmit':[('why',H_('m2','الحمد والتشميت والدعاء','عن أبي هريرة عن النبي ﷺ: إذا عطس أحدكم فليقل الحمد لله، وليقل له أخوه أو صاحبه يرحمك الله، فإذا قال له يرحمك الله فليقل يهديكم الله ويصلح بالكم. فالحديث يرتب ثلاث كلمات: حمد من العاطس، ثم دعاء بالرحمة من أخيه، ثم دعاء من العاطس بالهداية وإصلاح الحال. وفيه صيغ كل منهما كما وردت، أما حكم التشميت وخلاف الفقهاء فيه فليس في هذا الحديث.','صحيح البخاري (6224). https://sunnah.com/bukhari:6224'))],
'adabakl':[('why',H_('m2','سم الله وكل بيمينك','عن عمر بن أبي سلمة قال: كنت غلاماً في حجر رسول الله ﷺ، وكانت يدي تطيش في الصحفة، فقال لي رسول الله ﷺ: يا غلام سم الله، وكل بيمينك، وكل مما يليك. فما زالت تلك طعمتي بعد. فالحديث يجمع ثلاثة أوامر في الأكل: التسمية، والأكل باليمين، والأكل مما يلي الآكل. وتسبق الأمرَ في هذه الرواية حكايةُ موقف الغلام الذي كان يمد يده في أنحاء الصحفة، وليس في الحديث نص على حكمها عند المذاهب.','صحيح البخاري (5376). https://sunnah.com/bukhari:5376'))],
'mufattirat':[('why',H_('m1','من نسي فأكل وشرب','عن أبي هريرة عن النبي ﷺ: إذا نسي فأكل وشرب فليتم صومه، فإنما أطعمه الله وسقاه. فالحديث يخص من أكل أو شرب ناسياً، ويأمره بإتمام صومه، ويعلل ذلك بأن الله هو الذي أطعمه وسقاه. وهذا في الناسي وحده، ولا يشمل من أكل متعمداً.','صحيح البخاري (1933). https://sunnah.com/bukhari:1933'))],
}
cnt=0
for C in W:
  for L in C['lessons']:
    if L['id'] in add:
      ids={x['id'] for g in L['meaning'].values() for x in g}
      for g,it in add[L['id']]:
        if it['id'] in ids:
          n=max(int(i[1:]) for i in ids)+1; it['id']='m%d'%n
        ids.add(it['id']); L['meaning'][g].append(it); cnt+=1
lib.save(head,W,R,S);print(cnt)
